"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["92445"],{61178(e,t,n){n.d(t,{Ay:()=>r,RM:()=>o});var i=n(74848),s=n(28453);let o=[];function a(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"serious-advance-notice-this-week-begins-the-lectures-on-ch\xe1n-zh\u014Dng-shu\u014D-ch\xe1ns-traditional-chinese-medicine",children:"Serious Advance Notice: This Week Begins the Lectures on Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n's Traditional Chinese Medicine"})}),"\n",(0,i.jsxs)(t.blockquote,{children:["\n",(0,i.jsx)(t.p,{children:"2008/8/27 15:45:46"}),"\n"]}),"\n",(0,i.jsx)("div",{style:{color:"#FF0000",fontSize:"32px",fontWeight:"500",lineHeight:"180%"},children:(0,i.jsx)(t.p,{children:"Serious advance notice: this week begins the lectures on Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n's Traditional Chinese Medicine. Note \u2014 this is Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n's Traditional Chinese Medicine, not Traditional Chinese Medicine in general."})}),"\n",(0,i.jsxs)("div",{style:{color:"#0033FF",fontSize:"18px",fontWeight:"500"},children:[(0,i.jsx)(t.p,{children:"I had planned to go for physiotherapy, but now that's no longer necessary. Last night, this ID had someone come over to manually press and massage some key areas, combined with a needle of Western medicine, and it's already fully taken effect. Yesterday I only applied heavy treatment to the more seriously affected side, and now the other side actually seems to feel worse than the treated one \u2014 which means the results are quite good."}),(0,i.jsx)(t.p,{children:"I didn't dare trouble that extraordinary healer about this. People's thinking easily falls into their own self-designed plans. The extraordinary healer's goal is to tackle the most important illness, so naturally he doesn't care much for these minor ailments. And this time this ID was also wrong \u2014 I told the healer about this and he gave me a different medicine, but that medicine had a counteractive effect on the first one, causing the treatments for the main illness to diminish each other's efficacy. Later, the realization that struck this ID was that master chefs generally don't like washing dishes \u2014 these miscellaneous tasks should be delegated through division of labor to lower-level practitioners. So that's what happened last night. The reason I didn't mention it was that I didn't know how it would turn out, and I didn't want to jinx things by talking too much before seeing results. Fortunately, the outcome was superb."}),(0,i.jsx)(t.p,{children:"As for the current situation, this ID can tell you all very clearly: coming here is essentially a process of dissolving karma. The fewer troublesome people, the better. Just a few days ago, this ID mentioned here that the food wasn't great, and immediately a friend sent a text saying they'd send an older lady over with good food. This ID immediately texted back: \"Thank you, but absolutely don't.\" There should be N people here who know this ID's phone number, and even the hotel where I'm currently staying. One or two even know the room number. If something really happens to this ID, they'll see the blog and fly over immediately, so this ID really has nothing to worry about. Some of these friends only learned the blog address when they rushed over during this ID's last hepatic coma (as for the specifics, honestly, this ID still hasn't fully figured out what happened). Let me also tell them here: absolutely don't worry, I'm doing perfectly fine. If things go well, in two or three months I might be soaring like a dragon in the sky again. For now, just let me dissolve this karma quietly by myself."}),(0,i.jsx)(t.p,{children:"As for those matters of eating and cooking \u2014 actually, this ID rarely gets the chance to play around with that. As for being alone, this is this ID's normal state. From the early 1990s until now, this ID has also invested in quite a few things. In the end, they all finished up and I'd leave, and the normal state was not even knowing where the company's office was. For example, this ID once ran a finance magazine, being the earliest and largest investor. First of all, this ID's name wasn't on anything \u2014 not even listed among the publishers. Later, that magazine became incredibly influential nationwide, yet this ID never even figured out where its editorial office was. Apparently someone told me they moved locations several times. In the end, I sold my shares and exited without ever having sorted out the details. That's just this ID's typical style."}),(0,i.jsx)(t.p,{children:"It's probably habit \u2014 this ID has always been a lone ranger. More than ten-something years ago, the funds under management weren't exactly small for that era \u2014 over 10 billion in scale. Of course, it wasn't all this ID's money. Who uses their own money to do shady business? It was several groups of people pooling funds together, handing them over for unified management, unified entry and exit. At that time, there were quite a few positions. This ID's habit was to use the brokerage staff to place orders, with instructions given only by this ID. Back then, I could be sitting in a small county town in the Northeast and traverse the entire length of China and back N times within four hours. Of course, there were also experiences of flying from Harbin to Haikou within 24 hours, doing a bit of mischief in Beijing, Nanjing, and Guangzhou along the way."}),(0,i.jsx)(t.p,{children:"That five-star or quasi-five-star hotel in Harbin \u2014 whether it was run or managed by Southeast Asians, I can't really remember now. I've even forgotten the specific name. I just remember the floors were especially high and the heating was so intense it drove you crazy. That was still the 1990s, so it should have been one of the best hotels in the area. I stayed there for quite a number of days. Are there any friends from Harbin? Tell me about it and help this ID recover some lost memories."}),(0,i.jsx)(t.p,{children:"Unfortunately, much that's been lost can never be recovered. So cherishing the present is probably the best form of remembrance. Everything in a person's life is nothing but a process of constantly becoming memories. In the end, what can be preserved is only memories, and all your actions determine the color of those memories \u2014 whether they are nightmares or that faint hint of blue under the setting sun."})]}),"\n",(0,i.jsx)("div",{style:{color:"#336600",fontSize:"18px",fontWeight:"500"},children:(0,i.jsx)(t.p,{children:"There's nothing to say about the broader market \u2014 everything was covered in yesterday's analysis. Some self-righteous types don't even understand what this ID's theory actually is, yet they proclaim that this ID's theory has been destroyed by current market movements. For such people, the only choice is to ignore them \u2014 letting stupidity continue being stupid is the best punishment for stupidity. As for those who already have some grasp, you can naturally see how the current market movement is playing out within the framework. Note: the pattern mentioned in yesterday's analysis appears extremely frequently in bottom formations, and you must study it carefully. This is an unparalleled tool, because in reverse, it's the formation of tops \u2014 and this is all too common in the construction of historic tops."})}),"\n",(0,i.jsx)("div",{style:{color:"#FF0000",fontSize:"20px",fontWeight:"500"},children:(0,i.jsxs)(t.p,{children:["Alright, now this ID is heading out for a major shopping spree. The feeling of ",(0,i.jsx)("span",{style:{fontSize:"32px"},children:"massive construction projects"})," going on inside my body is getting stronger and stronger \u2014 mustn't waste this opportunity."]})})]})}function r(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(a,{...e})}):a(e)}},64132(e,t,n){n.r(t),n.d(t,{metadata:()=>i,default:()=>u,frontMatter:()=>r,contentTitle:()=>h,toc:()=>d,assets:()=>l});var i=JSON.parse('{"id":"timeline/confucius/chanmedicine","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/timeline/confucius/chanmedicine.md","sourceDirName":"timeline/confucius","slug":"/timeline/confucius/chanmedicine","permalink":"/en/timeline/confucius/chanmedicine","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"chanmedicine","title":"","hide_table_of_contents":true,"sidebar_label":"Serious Preview: This Week Begins Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n\'s Traditional Chinese Medicine Lectures (2008/8/27 15:45:46)"},"sidebar":"timelineSidebar","previous":{"title":"Some Idle Talk (2008/8/27 8:15:37)","permalink":"/en/timeline/zen/somewords"},"next":{"title":"Waiting for Policy and Technicals to Produce Resonance Effects (2008/8/28 15:10:21)","permalink":"/en/timeline/economics/waitingresonance"}}'),s=n(74848),o=n(28453),a=n(61178);let r={id:"chanmedicine",title:"",hide_table_of_contents:!0,sidebar_label:"Serious Preview: This Week Begins Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n's Traditional Chinese Medicine Lectures (2008/8/27 15:45:46)"},h,l={},d=[...a.RM];function c(e){return(0,s.jsx)(a.Ay,{})}function u(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}},28453(e,t,n){n.d(t,{R:()=>a,x:()=>r});var i=n(96540);let s={},o=i.createContext(s);function a(e){let t=i.useContext(o);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),i.createElement(o.Provider,{value:t},e.children)}}}]);